import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.RycU2wFZ.js";const m=JSON.parse('{"title":"Agent Frameworks: What They Provide","description":"","frontmatter":{},"headers":[],"relativePath":"learn/01-agent-basics/agent-frameworks.md","filePath":"learn/01-agent-basics/agent-frameworks.md","lastUpdated":1792595354000}'),n={name:"learn/01-agent-basics/agent-frameworks.md"};function r(i,e,l,d,p,c){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="agent-frameworks-what-they-provide" tabindex="-1">Agent Frameworks: What They Provide <a class="header-anchor" href="#agent-frameworks-what-they-provide" aria-label="Permalink to &quot;Agent Frameworks: What They Provide&quot;">​</a></h1><p>Agent applications often need to connect models to tools, preserve state, route requests, handle retries, and observe execution. Frameworks package some of these building blocks.</p><p>Common capabilities include model adapters, tool schemas and invocation, conversation state, workflow orchestration, structured output, tracing, and evaluation hooks. Frameworks vary: some focus on tool abstractions, while others provide graph workflows, multi-agent coordination, or hosted runtimes.</p><h2 id="choose-for-the-task" tabindex="-1">Choose for the task <a class="header-anchor" href="#choose-for-the-task" aria-label="Permalink to &quot;Choose for the task&quot;">​</a></h2><p>A predictable sequence may be easier to reason about as an explicit workflow. An agent loop is useful when the next step depends on intermediate findings. Multi-agent designs can divide work, but add coordination, latency, and failure points. Compare frameworks based on model support, integrations, state persistence, observability, deployment, testing, and how clearly you can understand their control flow.</p><h2 id="a-framework-is-not-a-safety-boundary" tabindex="-1">A framework is not a safety boundary <a class="header-anchor" href="#a-framework-is-not-a-safety-boundary" aria-label="Permalink to &quot;A framework is not a safety boundary&quot;">​</a></h2><p>A framework does not guarantee correct model decisions, protect credentials, authorize payments, or make retries safe. The application still owns authentication, authorization, validation, resource and spending limits, idempotency, recovery, and privacy-aware audit logs. Keep critical policy in deterministic code outside the prompt.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Application policy and credentials</span></span>
<span class="line"><span>             ↓</span></span>
<span class="line"><span>Framework: model, tools, task loop</span></span>
<span class="line"><span>             ↓</span></span>
<span class="line"><span>Narrowly scoped services and APIs</span></span></code></pre></div><p>Treat the framework as an orchestration component, not the authority for every action.</p>`,9)])])}const u=a(n,[["render",r]]);export{m as __pageData,u as default};
